<?php
require_once __DIR__.'/helpers.php';
$id=(int)($_GET['id']??0);$stmt=$pdo->prepare("SELECT f.*,e.position,e.employee_code FROM operational_funds f LEFT JOIN employees e ON e.id=f.employee_id WHERE f.id=:id");$stmt->execute([':id'=>$id]);$fund=$stmt->fetch(PDO::FETCH_ASSOC);if(!$fund)redirect('pages/finance/operational_funds.php?error=Dana tidak ditemukan');
$stmt=$pdo->prepare("SELECT m.*,a.account_name,p.project_name,(SELECT COUNT(*) FROM operational_fund_movements r WHERE r.source_module='finance' AND r.source_table='operational_fund_movements' AND r.source_id=m.id) AS reversed_count FROM operational_fund_movements m LEFT JOIN finance_accounts a ON a.id=m.account_id LEFT JOIN projects p ON p.id=m.project_id WHERE m.fund_id=:id ORDER BY m.movement_date DESC,m.id DESC");$stmt->execute([':id'=>$id]);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
$pageTitle='Detail Dana Operasional - Nukari';require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?>
<main class="main-content"><div class="page-header d-flex justify-content-between"><div><h1 class="fw-bold mb-1"><?= f_e($fund['person_name']); ?></h1><p class="text-muted mb-0"><?= f_e($fund['fund_code']); ?> · satu saldo berkelanjutan untuk PIC ini</p></div><a class="btn btn-outline-success" href="<?= base_url('pages/finance/operational_funds.php'); ?>">Kembali</a></div>
<div class="row g-3 mb-4"><?php foreach(['Diterima'=>$fund['total_received'],'Dipakai'=>$fund['total_used'],'Dikembalikan'=>$fund['total_returned'],'Saldo'=>$fund['current_balance']] as $label=>$amount): ?><div class="col-md-3"><div class="panel h-100"><div class="text-muted small"><?= $label; ?></div><div class="fs-5 fw-bold <?= $label==='Saldo'&&$amount<0?'text-danger':''; ?>"><?= rupiah($amount); ?></div></div></div><?php endforeach; ?></div>
<?php if((float)$fund['current_balance']<0): ?><div class="alert alert-danger rounded-4"><b>Saldo minus.</b> Perusahaan memiliki hutang <?= rupiah(abs($fund['current_balance'])); ?> kepada <?= f_e($fund['person_name']); ?>. Pemberian dana berikutnya otomatis mengurangi hutang ini terlebih dahulu.</div><?php endif; ?>
<?php if(!empty($_GET['message'])): ?><div class="alert alert-success rounded-4"><?= f_e($_GET['message']); ?></div><?php endif; ?>
<?php if(!empty($_GET['error'])): ?><div class="alert alert-danger rounded-4"><?= f_e($_GET['error']); ?></div><?php endif; ?>
<div class="panel"><h5 class="fw-bold mb-3">Seluruh Mutasi</h5><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Tanggal</th><th>Jenis</th><th>Saldo</th><th>Akun</th><th>Project</th><th>Keterangan</th><th class="text-end">Nominal</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= date('d M Y',strtotime($r['movement_date'])); ?></td><td><?= f_e(opfund_movement_label($r['movement_type'])); ?></td><td><?php if(($r['posting_mode']??'posted')==='historical'): ?><span class="badge bg-secondary-subtle text-secondary">Historis</span><?php if(!empty($r['historical_reason'])): ?><div class="small text-muted mt-1"><?= f_e($r['historical_reason']); ?></div><?php endif; ?><?php else: ?><span class="badge bg-success-subtle text-success">Terposting</span><?php endif; ?></td><td><?= f_e($r['account_name']?:'-'); ?></td><td><?= f_e($r['project_name']?:'-'); ?></td><td><?= f_e($r['description']?:'-'); ?></td><td class="text-end fw-bold"><?= rupiah($r['amount']); ?></td><td><?php if(($r['source_module']??'')==='finance'&&($r['source_table']??'')==='operational_funds'&&in_array($r['movement_type'],['receive','return'],true)&&(int)$r['reversed_count']===0): ?><form method="POST" action="<?= base_url('pages/finance/operational_fund_reverse.php?id='.(int)$r['id']); ?>" onsubmit="const reason=prompt('Tuliskan alasan koreksi mutasi:');if(!reason||!reason.trim())return false;this.reason.value=reason.trim();return confirm('Buat mutasi pembalik dan hitung ulang saldo?');"><?= csrf_field(); ?><input type="hidden" name="reason" value=""><button class="btn btn-sm btn-outline-danger">Koreksi/Balik</button></form><?php elseif((int)$r['reversed_count']>0): ?><span class="badge bg-secondary">Sudah dibalik</span><?php else: ?><span class="text-muted">Dari modul sumber</span><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="8" class="text-center text-muted">Belum ada mutasi.</td></tr><?php endif; ?></tbody></table></div></div></main><?php require_once __DIR__.'/../../includes/footer.php'; ?>
